import{_ as e,c as t,o as a,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易本義通釋卷十","description":"周易本義通釋 - 周易本義通釋卷十","frontmatter":{"title":"周易本義通釋卷十","description":"周易本義通釋 - 周易本義通釋卷十"},"headers":[],"relativePath":"classics/benyi-tongshi/011.md","filePath":"classics/benyi-tongshi/011.md"}'),i={name:"classics/benyi-tongshi/011.md"};function n(r,p,o,c,_,l){return a(),t("div",null,[...p[0]||(p[0]=[s('<h1 id="周易本義通釋卷十" tabindex="-1">周易本義通釋卷十 <a class="header-anchor" href="#周易本義通釋卷十" aria-label="Permalink to “周易本義通釋卷十”">​</a></h1><p>欽定四庫全書</p><p>元胡炳文撰</p><p>乾剛坤柔，比樂師憂。</p><p>臨觀之義，或與或求。</p><p>以我臨物曰與，物來觀我曰求。或曰：二卦互有與求之義。屯見而不失其居，蒙離而著。</p><p>屯震遇坎，震動故見坎險不行也。蒙坎遇艮，坎幽昩，艮光明也。或曰：屯以初言，蒙以二言。震，起也。艮，止也。</p><p>大畜，時也。無妄，災也。</p><p>止健者，時有適然。無妄而災自外至。</p><p>萃聚，而升不來也。謙輕，而豫怠也。</p><p>噬嗑，食也。賁，無色也。白受採。兌見而巽伏也。</p><p>兌陰外見，巽陰內伏。</p><p>隨，無故也。蠱則飭也。</p><p>隨前無故，蠱後則飭。剝，爛也。復，反也。晉，晝也。明夷，誅也。誅，傷也。井通，而困相遇也。</p><p>剛柔相遇，而剛見揜也。鹹，速也。恆，久也。鹹速恆久。</p><p>渙，離也。節，止也。解，緩也。蹇，難也。睽，外也。家人，內也。否、泰，反其類也。</p><p>大壯則止，遁則退也。止謂不進。大有，眾也。同人，親也。革，去故也。鼎，取新也。小過，過也。中孚，信也。豐，多故。親寡，旅也。</p><p>既明且動，其故多矣。離上而坎下也。火炎上，水潤下。</p><p>小畜，寡也。履，不處也。不處，行進之義。需，不進也。訟，不親也。大過，顛也。姤，遇也，柔遇剛也。漸，女歸待男行也。頤，養正也。既濟，定也。歸妹，女之終也；未濟，男之窮也。夬，決也，剛決柔也，君子道長，小人道憂也。自大過以下卦不反對，或疑其錯簡，今以韻協之，又似非誤，未詳何義。通曰：易終於雜卦，而交易變易之義愈可見矣。每一卦反覆為兩卦，而剛柔吉凶每每相反，此變易之義也。自乾坤至困三十卦，與上經之數相當，而雜下經十二卦於其中；自鹹至夬三十四卦，與下經之數相當，而雜上經十二卦於其中，此交易之義也。或曰：「此偶然爾。」愚曰：「非偶然也，皆理之自然也。坎離，交之中者，本居上經三十卦內，今附於下三十四卦；震艮巽兌，交之偏者，本居下經三十四卦內，今附於上三十卦。至若無反對者，上經六卦，下經二卦，今附於上者二卦，附於下者六卦，皆交易之義也。」十二月卦氣，除乾坤外，上經泰否、臨觀剝復，陰之多於陽者十二；下經遁壯、姤夬，陽之多於陰者十二。今雜卦移否、泰於三十四卦之中，而陰陽之多少復如之。特在上經者三十六畫，在下經者二十四畫。今附於上者二十四畫，附於下者三十六畫，愈見其交易之妙爾。若合六十四卦論之，上經三十卦，陰爻之多於陽者八；下經三十四卦，陽爻之多於陰者亦八。今則附於三十卦者，陽爻七十二，陰爻一百八，而陰多於陽者三十六。附於三十四卦者，陽爻一百二十，陰爻八十四，而陽之多於陰者亦三十六。以反對論，上經陰之多於陽者四，下經陽之多於陰者亦四。今則附於上者，陽爻三十九，陰爻五十七，而陰之多於陽者十八。附於下者，陽爻六十九，陰爻五十一，而陽之多於陰者亦十八。或三十六，或十八，互為多少，非特可見陰陽交易之妙，而三十六宮之妙愈可見矣。是豈聖人之心思智慮之所為哉？愚固曰：伏羲之畫，文王、周公、孔子之言，皆天也。本義謂自大過以下，卦不反對，或疑其錯簡，今以韻協之，又似非誤，未詳何義。愚竊以為「雜物撰德，非其中爻不備」，此蓋指中四爻互體而言也。先天圖之左互復、頤、既濟、家人、歸妹、睽、夬、乾八卦，右互姤、大過、未濟、解、漸、蹇、剝、坤八卦。此則於右取姤、大過、未濟、漸四卦，於左取頤、既濟、歸妹、夬四卦，各舉其半，可兼其餘矣。是雖所取不能無雜，蓋此謂雜卦，而互體又其最雜者也。上三十卦，終之以困，柔揜剛也。下三十四卦，終之以夬，剛決柔也。柔揜剛，君子不失其所亨；剛決柔，君子道長，小人道憂矣。然則天地間，剛柔每每相雜，至若君子之為剛，小人之為柔，決不可使相雜也。雜卦之末，特分別君子小人之道言之。聖人贊化育、扶世變之意微矣。始於乾，終於夬。或曰：夬之一陰決盡，則為乾也。以皇極經世考之，乾已會之終，堯舜雍熙之世也。十二萬九千六百年，安得常如自夬而乾所值堯舜之世哉！嗚呼！任賢勿貳，去邪勿疑，疑謀勿成，即此所謂夬之決也。後之蒞天下者，亦法堯舜而已矣。周易本義通釋卷十，</p>',19)])])}const m=e(i,[["render",n]]);export{h as __pageData,m as default};
